import js from "@eslint/js";
import globals from "globals";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import tseslint from "typescript-eslint";
import eslintConfigPrettier from "eslint-config-prettier/flat";

export default tseslint.config(
  {
    // `expo/` is a standalone React Native project with its own toolchain.
    // `src/convex/_generated` is Convex codegen output — regenerated by
    // `convex dev`, so its embedded eslint-disable directives are part of the
    // template and hand-editing them would be overwritten. Generated code is
    // not linted.
    ignores: ["dist", "expo/**", "src/convex/_generated/**"],
  },
  {
    extends: [
      js.configs.recommended,
      ...tseslint.configs.recommended,
      eslintConfigPrettier,
    ],
    files: ["**/*.{ts,tsx}"],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    plugins: {
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],
    },
  },
  {
    // vly-toolbar-readonly.tsx starts with "DO NOT MODIFY THIS FILE. THIS
    // FILE IS READ-ONLY" (platform-managed tooling), so its mixed
    // component/function exports cannot be restructured. This rule only
    // affects dev fast-refresh, never runtime behaviour — scoped off for
    // this one file.
    files: ["vly-toolbar-readonly.tsx"],
    rules: {
      "react-refresh/only-export-components": "off",
    },
  },
);
